use vstd::prelude::*;

verus! {

fn get_first_elements(lst: Vec<Vec<i32>>) -> (result: Vec<i32>)
    requires
        // Every inner vector is non-empty
        forall|i: int| 0 <= i < lst.len() ==> lst[i].len() > 0,
    ensures
        // Output has same length as input
        result.len() == lst.len(),
        // Each output element is the first element of the corresponding inner vector
        forall|i: int| 0 <= i < lst.len() ==> result[i] == lst[i][0],
{
    let n: usize = lst.len();
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            i <= n,
            // out contains exactly the first elements of lst[0..i)
            out.len() == i,
            forall|j: int| 0 <= j < i ==> out[j] == lst[j][0],
            // keep the original precondition available in the loop
            forall|k: int| 0 <= k < n ==> lst[k].len() > 0,
        decreases n - i,
    {
        // Safe because of the (loop-carried) non-empty guarantee:
        // lst[i].len() > 0 hence index 0 is valid.
        let first: i32 = lst[i][0];
        out.push(first);
        i = i + 1;
    }

    out
}

} // verus!

